import {formatSalary} from './salary-progression.js?v=0.31.0';
import {educationRouteEvidence} from './education-route-evidence.js?v=0.31.0';
import {freshCareerScenario,cleanCareerScenario,fundingScenario,loanCohort} from './financial-math.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
import {collegeExamples} from './finance-data.js?v=0.31.0';
import {educationCostEvidence} from './education-cost-evidence.js?v=0.31.0';
import {commonCostEvidence} from './common-cost-data.js?v=0.31.0';
import {calculateLifestyle} from './lifestyle.js?v=0.31.0';
import {escapeHTML as h} from './html.js?v=0.31.0';
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export function studyCostReference(id){const o=occupationById(id);if(!o)return null;const level=o.finance?.credentialLevel||(id==='clinical-psychologist'?'graduate':'training'),ut=collegeExamples.find(x=>x.id==='ut-austin-resident'),acc=collegeExamples.find(x=>x.id==='acc-district'),e=educationCostEvidence[id],c=commonCostEvidence[id];let cost=0,years=0,parts=[],sources=[];
 if(id==='hairdresser'){years=.75;const school=15700+3200+50+25,living=acc.housing+acc.transportation+acc.other,health=1800,licensing=250;cost=school+living+health+licensing;parts.push({label:'Aveda Austin · 1,000-hour cosmetology school costs',amount:school,scope:'Published tuition $15,700 + kit $3,200 + application $50 + state registration $25. These are school costs, not all makeup or body-art training requirements.'},{label:'Nine months of living during study',amount:living,scope:'Planning allowance using ACC housing, transport and personal costs for nine academic months. The named school describes about nine months for its shorter route; actual schedules and completion vary.'},{label:'Health coverage reserve',amount:health,scope:'$200 per month for nine months, an editable planning assumption.'},{label:'Exams and initial licensing reserve',amount:licensing,scope:'$250 planning allowance, not a quoted state or testing fee.'});sources.push('https://avedaarts.edu/campus/tx/austin/','https://www.tdlr.texas.gov/barbering-and-cosmetology/individuals/apply-cosmetologist.htm',acc.sourceURL);}
 else if(id==='architecture'){const tuition=ut.tuitionMax*5,living=(ut.housingMax+ut.transportation+ut.other)/9*12*5,books=ut.books*5;cost=tuition+living+books;years=5;parts.push({label:'Five-year BArch · UT Austin resident planning example',amount:cost,scope:'Five current upper-end undergraduate tuition years, books, and twelve-month living allowances. Uses a university budget range, not a program bill. Supervised experience and architecture exams follow separately.'});sources.push(ut.sourceURL,'https://soa.utexas.edu/architecture/undergraduate');}
 else if(educationRouteEvidence[id]?.amounts.listedProgramResident){const named=educationRouteEvidence[id];years=named.duration.months/12;const program=named.amounts.listedProgramResident.value,living=(acc.housing+acc.transportation+acc.other)/9*12*years,health=2400*years;cost=program+living+health;parts.push({label:named.institution+' · '+named.program,amount:program,scope:named.amounts.listedProgramResident.scope},{label:'Living during study · editable planning allowance',amount:living,scope:named.duration.months+' months, using ACC housing, transport and personal allowances spread across nine academic months. Books are already in the program total.'},{label:'Health coverage reserve · planning allowance',amount:health,scope:'$200 per month assumption; not a quote, aid award or known personal premium. Change for existing coverage and medical needs.'});sources.push(...named.sourceURLs,acc.sourceURL);}
 else if(level==='bachelor'||level==='graduate'){cost=ut.totalMin*4;years=4;parts.push({label:'Four years of college · UT Austin resident budget reference',amount:cost,scope:'4 × current fall/spring attendance budget; summer living is separate.'});sources.push(ut.sourceURL);}
 else if(level==='associate'){cost=acc.totalMin*2;years=2;parts.push({label:'Two years · ACC in-district attendance reference',amount:cost,scope:'2 × current fall/spring budget before aid; not a credential-specific quote.'});sources.push(acc.sourceURL);}
 if(years>0&&!['architecture','nursing','emt','hairdresser'].includes(id)){const c=level==='associate'?acc:ut,summer=(c.totalMin-c.tuitionMin)/9*3*years;cost+=summer;parts.push({label:'Summer living reserve · '+years+' years',amount:summer,scope:'Three extra living months per year, using the published non-tuition academic-year allowance divided across nine months. An editable planning assumption, not another tuition charge.'});}
 if(level==='graduate'){
  let add=0,extra=2,label='Further study · graduate attendance reference';
  if(educationRouteEvidence[id]?.amounts.totalCOAResident){const named=educationRouteEvidence[id];extra=named.duration.months/12||named.duration.years;add=named.amounts.totalCOAResident.value;label=named.institution+' · '+named.program+' · published attendance budget';sources.push(...named.sourceURLs);}
  else if(e?.amounts?.programTotalResident){extra=e.duration?.months/12||2;add=e.amounts.programTotalResident.value;label=e.institution+' · published full-program attendance budget';}
  else if(id==='law'){const continuing=e.yearRows[0],academic=e.amounts.totalResident.value+2*continuing.totalResident,summer=((63899-38236-1500)/9*3)*3;add=academic+summer;extra=3;label=e.institution+' · first year + two continuing years + summer living reserve';}
  else if(e?.yearRows?.length&&e.yearRows.every(r=>Number.isFinite(r.totalResident))){add=e.yearRows.reduce((n,r)=>n+r.totalResident,0);extra=e.yearRows.length;label=e.institution+' · published program-year budgets';}
  
  else if(e?.yearRows?.length&&e.yearRows.every(r=>Number.isFinite(r.tuitionFeesResident))){extra=e.yearRows.length;add=e.yearRows.reduce((n,r)=>n+r.tuitionFeesResident+(r.housingFoodEstimate||22000)+(r.healthInsuranceEstimate||3500),0);label=e.institution+' · tuition plus living/health planning allowances';}
  else if(id==='physician'){extra=4;add=4*(e.amounts.tuitionFeesResident.value+25500);label='Dell MD · four current tuition/fee years + living/health allowance';}
  else if(id==='veterinary'){extra=4;add=4*e.amounts.firstYearTotalResident.value;label=e.institution+' · four-year scenario using the published first-year attendance budget';}
  else if(id==='pharmacy'){extra=4;add=4*(e.amounts.fallSpringTuitionResident.value+25500);label='UT PharmD · four fall/spring tuition years + living/health allowance';}
  else if(e?.amounts?.tuitionFeesResident12Credit){extra=3;add=e.amounts.tuitionFeesResident12Credit.value*8+extra*25500;label=e.institution+' · eight semester-rate examples + three living/health allowances';}
  else if(e?.programCredits||e?.duration){
   extra=(e.duration?.months||e.duration?.planningMonths||e.duration?.maxMonths||({ 'speech-language':24 }[id])||24)/12;
   const a=e.amounts,full=a.programTotalResident?.value,tuition=a.programTuitionResident?.value||a.tuitionTechnologyResident?.value||a.tuitionResident?.value||a.tuitionResident?.min||0;
   const semester=/semester/i.test(a.tuitionResident?.label||'')&&!a.programTuitionResident;
   const plannedTuition=semester?tuition*(e.programCredits||18)/(/12.credit/i.test(a.tuitionResident.label)?12:9):tuition;
   const living=a.annualTotalResident?((a.annualTotalResident.value-a.annualTuitionResident.value)/9*12*extra):25500*extra;
   add=full||plannedTuition+living;label=e.institution+' · '+(full?'published program attendance total':'degree-specific tuition benchmark + living allowance');
  }
  else {const g=educationCostEvidence.genericGraduate;extra=['clinical-psychologist','school-psychology'].includes(id)?5:2;add=g.amounts.totalResident.min*extra;label='UT Austin graduate attendance reference · '+extra+' years before funding';sources.push(...g.sourceURLs);}
  parts.push({label,amount:add,scope:'Planning sum in current-source dollars. Confirmed grants, funding, and personal contributions are entered below.'});cost+=add;years+=extra;sources.push(...(e?.sourceURLs||[]));
 }
 if(!parts.length&&id==='electrician'){const named=educationRouteEvidence.electrician;cost=named.amounts.tuitionAndListedFeesResident.value+named.amounts.apprenticeLicense.value;years=1;parts.push({label:'Optional ACC electrical certificate + initial apprentice license',amount:cost,scope:'Listed 25-credit, two-semester tuition/fee plan plus $20 license. Books, tools and living are separate. Supplemental preparation, not a substitute for supervised apprenticeship hours or journeyman licensing.'});sources.push(...named.sourceURLs);}
 if(!parts.length&&c?.amount){const a=c.amount;cost=typeof a==='number'?a:a.value??a.min??0;years=/annual|year|fall|spring/i.test(a.unit||'')?1:0;parts.push({label:c.headline,amount:cost,scope:c.scope});sources.push(...c.sourceURLs);}
 if(!parts.length&&typeof c?.optionalExample?.amount==='number'){cost=c.optionalExample.amount;parts.push({label:c.optionalExample.institution+' · '+c.optionalExample.label,amount:cost,scope:c.optionalExample.scope});sources.push(...c.optionalExample.sourceURLs);}
 if(!parts.length)parts.push({label:'Employer training or experience · tuition-only reference',amount:0,scope:'This route does not assume a separately purchased college program. $0 is tuition in this scenario, not a claim that training, equipment, licensing or living are free. Employer-paid arrangements and optional schools differ.'});
 return {cost,years,parts,sourceNotes:educationRouteEvidence[id]?.limitations||[],sources:[...new Set(sources)]};}
export function careerScenario(s,id){const r={...freshCareerScenario(),...s.finance?.careerScenarios?.[id]},reference=studyCostReference(id);if(r.cost===''){r.cost=String(Math.round(reference?.cost||0));r.studyYears=String(reference?.years||0);r.interest=String((occupationById(id)?.finance?.credentialLevel==='graduate'||id==='clinical-psychologist')?loanCohort.graduate:loanCohort.undergraduate);}return cleanCareerScenario(r);}
const input=(id,key,label,value,step='1')=>`<label class="scenario-field" for="scenario-${key}"><span>${label}</span><input id="scenario-${key}" type="number" min="0" step="${step}" data-career-scenario="${h(id)}" data-scenario-field="${key}" value="${h(value)}"></label>`;
export function careerFundingPanel(s,id,{reference=studyCostReference(id)}={}){const p=careerScenario(s,id),r=fundingScenario(p);if(!r||r.status!=='scenario')return '';return `<section class="career-funding" id="career-funding"><div class="section-heading"><div><span class="overline">EDUCATION → WORKING LIFE</span><h2>How to pay for training</h2></div><span class="evidence-badge">Estimated budget · you can edit it</span></div><div class="funding-summary"><article><span>Training cost before aid</span><strong>${usd(r.cost)}</strong></article><article><span>After grants</span><strong>${usd(r.netPrice)}</strong></article><article><span>Your loan payment</span><strong>${usd(r.paymentWithStudyInterest)}<small> / month</small></strong></article></div>${r.unfunded>0?`<p class="unfunded-budget"><strong>${usd(r.unfunded)} still needs funding.</strong> Add grants, savings, or borrowing to see a fuller payment estimate.</p>`:''}<details class="more-info"><summary>Edit grants, savings and loans</summary><div class="scenario-fields">${input(id,'cost','Total study budget',p.cost)}${input(id,'grants','Confirmed grants & scholarships',p.grants)}${input(id,'cash','Cash contribution',p.cash)}${input(id,'studyEarnings','Planned earnings during study',p.studyEarnings)}${input(id,'parentFunding','Parent funding · their repayment stays separate',p.parentFunding)}${input(id,'borrowing','Your loan principal',p.borrowing)}${input(id,'interest','Annual loan interest %',p.interest,'.01')}${input(id,'years','Repayment years · comparison scenario',p.years)}${input(id,'studyYears','Years before repayment',p.studyYears,'.01')}</div><p>Funding still needed: <strong>${usd(r.unfunded)}</strong>. Loans help pay the price; grants reduce it. This calculation does not assume that a lender will approve the amount.</p><p>The payment includes a simple study-interest scenario with borrowing spread evenly across the study period. Subsidies, actual disbursement dates, fees, and repayment-plan terms can change the result.</p><label class="check-line"><input type="checkbox" data-career-scenario="${h(id)}" data-scenario-field="debtLinked" ${p.debtLinked?'checked':''}> Include this payment in my Austin lifestyle</label></details><details class="more-info"><summary>The route behind this budget</summary>${reference.parts.map(x=>'<p><strong>'+h(x.label)+' · '+usd(x.amount)+'</strong><br>'+h(x.scope)+'</p>').join('')}${reference.sourceNotes.length?'<details class="more-info"><summary>Source dates & program detail</summary>'+reference.sourceNotes.map(t=>'<p>'+h(t)+'</p>').join('')+'</details>':''}<p>These current-dollar reference budgets are a starting scenario. They do not assume admission, an aid award, or a future tuition rate. The college rows include a separate summer living reserve; named program rows retain their own stated coverage. Adjust costs outside those periods. Borrowing defaults to zero until you choose it.</p><p>${reference.sources.map(u=>'<a href="'+h(u)+'" target="_blank" rel="noopener">Published education source ↗</a>').join(' · ')} · <a href="${loanCohort.sourceURL}" target="_blank" rel="noopener">2026–27 federal loan rates ↗</a></p></details></section>`;}
export function workScenarioPanel(s,id,inputs){const p=careerScenario(s,id),r=calculateLifestyle(inputs);return `<section class="work-scenario"><h2>Change hours or work for yourself</h2><p>Compare your work options.</p><div class="work-mode" role="group" aria-label="Employment arrangement">${['employee','independent'].map(v=>`<button data-action="scenario-work-mode" data-id="${h(id)}" data-value="${v}" aria-pressed="${p.workMode===v}">${v==='employee'?'Employee':'Independent work'}</button>`).join('')}</div><details class="more-info"><summary>Hours, working weeks & expenses</summary><div class="scenario-fields">${input(id,'weeklyHours','Paid hours each week',p.weeklyHours)}${input(id,'paidWeeks','Paid weeks each year',p.paidWeeks)}${p.workMode==='independent'?input(id,'businessExpenses','Business expenses each month',p.businessExpenses):''}</div>${p.workMode==='independent'?'<p>For this comparison, the pay amount becomes an editable annual-receipts scenario. Receipts minus business expenses give profit. Self-employment tax, personal income tax, health costs, and cash retirement saving are then deducted. Employee wage data does not establish a business’s revenue.</p>':'<p>This scales the full-time annual-pay reference by chosen paid hours and weeks. It is a scenario, not a promise that a job offers that schedule. Current employer contracts and teacher schedules use their published annual amount at the default setting.</p>'}</details>${r.status==='illustration'?`<div class="work-net"><span>${p.workMode==='independent'?'Operating profit':'Pay at your chosen hours'}</span><strong>About ${formatSalary(r.annualProfit)} / year</strong><span>After taxes, retirement & health</span><strong>About ${usd(Math.round(r.takeHome/50)*50)} / month</strong></div>`:''}</section>`;}
export function lifestyleStressPanel(inputs){const cases=[['Your chosen picture',inputs],['10% less income',{...inputs,gross:String(Number(inputs.gross)*.9)}],['15% higher rent or home price',{...inputs,rent:String(Number(inputs.rent)*1.15),homePrice:String(Number(inputs.homePrice)*1.15)}]],rows=cases.map(([title,p])=>({title,r:calculateLifestyle(p)})).filter(x=>x.r.status==='illustration');return `<details class="more-info resilience-panel"><summary>More info · what if costs rise?</summary><p>Try a tougher month. These are comparisons, not forecasts.</p><div class="resilience-grid">${rows.map(x=>`<article class="${x.r.remaining>=0?'fit-room':'fit-tradeoffs'}"><span>${x.title}</span><strong>${usd(Math.abs(x.r.remaining))} / month</strong><span>${x.r.remaining>=0?'left after your choices':'more than available income'}</span></article>`).join('')}</div></details>`;}

export function trainingFundingNote(state,id){const p=careerScenario(state,id),r=fundingScenario(p);return r?.status==='scenario'&&r.unfunded>0?'<p class="funding-condition"><strong>Training still needs funding.</strong> This pay comparison includes only the loan payments you entered.</p>':'';}
